function adaptiveLevel(t){let s=st.stats[t]||{c:0,n:0},acc=topicAccuracy(t),m=adaptiveMeta(),target;if(s.n<3)target=Math.round((m.min+m.max)/2);else if(acc>=.88)target=m.max;else if(acc>=.75)target=Math.min(m.max,m.min+2);else if(acc>=.58)target=Math.min(m.max,m.min+1);else target=m.min;return Math.max(m.min,Math.min(m.max,target))}
