function renderSolo(){answered=false;$("soloNext").disabled=true;$("soloNext").textContent=(i===soloTotal-1?(mode==="boss"?"Finish Boss Shift":mode==="quest"?"Finish Process Paniolo":"Finish Session"):"Next");current=deck[i];let surprise=mode!=="exam"&&mode!=="alarm"&&mode!=="quest"&&mode!=="boss"&&Math.random()<.15;if(surprise){let sp=mode==="adaptive"?adaptivePool().filter(q=>q.y==="scenario"):bank.filter(q=>q.y==="scenario");if(sp.length)current=shuffle(sp)[0]}$("soloAlarm").classList.toggle("hidden",!surprise);let isProcessBoss=mode==="quest"&&current.level==="Process Paniolo"&&String(current.q||"").startsWith("PROCESS PANIOLO:");$("processBossMark").classList.toggle("hidden",!isProcessBoss);$("soloMode").textContent=mode==="quest"?(current.stageIcon+" "+current.stage):(mode==="adaptive"?adaptiveLabel():(surprise?"BRAH… ALARM!":mode.toUpperCase()));$("soloCount").textContent=mode==="quest"?((i+1)+"/"+soloTotal+" • "+current.level):((i+1)+"/"+soloTotal);$("soloTopic").textContent=mode==="quest"?(current.t+" • Difficulty "+current.d):(mode==="adaptive"?(adaptiveMeta().label+" • "+current.t+" • "+(["","Easy Kine","Working","Mean","Mayjah","DRC Mode"][current.d]||("Difficulty "+current.d))):current.t);$("soloQ").textContent=current.q;$("soloFeedback").textContent=mode==="quest"?"Run da process — choose the BEST or FIRST operational answer.":"Choose the best answer.";$("soloA").innerHTML="";let order=current.a.map((_,x)=>x);if(mode==="quest"||mode==="adaptive"){let pattern=[2,0,3,1,1,3,0,2],target=pattern[i%pattern.length],ci=order.indexOf(current.c);[order[ci],order[target]]=[order[target],order[ci]]}order.forEach((orig,j)=>{let b=document.createElement("button");b.className="answer";b.textContent=String.fromCharCode(65+j)+". "+current.a[orig];b.dataset.orig=String(orig);b.onclick=()=>answerSolo(orig);$("soloA").appendChild(b)});renderSelfCards()}
function explainAnswer(q){let why="",tip="";const correct=q.a[q.c];
  const exact={
    "Flow is 2.0 MGD and BOD is 180 mg/L. Approximate BOD load is:":{why:"Use the standard loading formula: lb/day = MGD × mg/L × 8.34. Here, 2.0 × 180 × 8.34 = 3,002.4 lb/day, which rounds to 3,002 lb/day.",tip:"For wastewater loading problems, remember MGD × mg/L × 8.34 = lb/day."},
    "A tank holds 1.0 MG and flow is 2.0 MGD. Approximate hydraulic detention time is:":{why:"Detention time = tank volume ÷ flow. 1.0 MG ÷ 2.0 MGD = 0.5 day. Multiply by 24 hours/day to get 12 hours.",tip:"Keep volume and flow units compatible, then convert days to hours when needed."},
    "A 30-minute settled sludge volume is 230 mL/L and MLSS is 2,300 mg/L. Approximate SVI is:":{why:"SVI = settled sludge volume (mL/L) ÷ MLSS (g/L). 2,300 mg/L = 2.3 g/L, so 230 ÷ 2.3 = 100 mL/g.",tip:"Convert MLSS from mg/L to g/L before calculating SVI."}
  };
  if(exact[q.q])return exact[q.q];
  if(/FIRST|first|best approach|best operational|best general|strongest supervisory|strongest concern|prioritize/i.test(q.q)){why="The correct choice follows good troubleshooting order: verify the actual condition, protect safety/compliance and treatment capacity, then make a controlled adjustment based on what the plant is really doing.";tip="Best-FIRST-action questions usually reward verification and stabilization before a large process change."}
  else if(q.t==="Clarifiers"){why="Secondary clarifier performance depends on settling, solids inventory, blanket depth, hydraulic loading, and reliable RAS removal. The correct answer addresses the condition most directly tied to solids separation.";tip="Read blanket, RAS, settleability, and effluent TSS together instead of chasing one number."}
  else if(q.t==="Activated Sludge"){why="Activated sludge control is about keeping the right biological solids inventory and environment for the microorganisms. The correct answer best matches how RAS/WAS, SRT, loading, DO, or settleability affects that biomass.";tip="Connect each adjustment to what it changes: RAS moves solids; WAS controls solids inventory/SRT; air supports biological activity."}
  else if(q.t==="Nitrification"){why="Nitrifiers need enough oxygen, alkalinity, suitable pH/temperature, and sufficient SRT to remain in the system. The correct answer identifies the factor most directly connected to ammonia conversion.";tip="When ammonia rises, check DO, SRT, loading, alkalinity/pH, and temperature before making a blind adjustment."}
  else if(q.t==="Pumps"||q.t==="Equipment"){why="The correct answer matches the equipment symptoms and keeps troubleshooting focused on the hydraulic, electrical, or mechanical condition that can actually produce them.";tip="Verify the equipment condition safely before increasing speed, repeatedly resetting, or bypassing protection."}
  else if(q.t==="Digestion"||q.t==="Solids"){why="Solids treatment depends on stable loading, mixing, contact, and biological conditions. The correct answer addresses the change most likely to affect stability or equipment reliability.";tip="Trend loading, mixing, pH, volatile acids/alkalinity, gas production, and equipment condition together."}
  else if(q.t==="Disinfection"){why="Effective disinfection depends on actual chemical delivery or intensity, wastewater demand, flow, and adequate contact conditions. The correct answer checks those factors before assuming the process is working as commanded.";tip="Verify actual dose/feed and process demand—not just the setpoint."}
  else if(q.t==="Safety"){why="The correct answer puts personnel safety and verified operating conditions ahead of production pressure or alarm resetting.";tip="Safety controls and verification come before troubleshooting shortcuts."}
  else if(q.t==="Process Control"){why="Good process control uses verified trends and related indicators to identify the limiting condition before making controlled changes. The correct answer follows that approach.";tip:"One number is a clue; multiple verified trends tell the plant story."}
  else if(q.t==="Math"){why="The correct answer comes from applying the wastewater calculation with consistent units and checking that the result is reasonable.";tip:"Write the formula first, keep units visible, then calculate."}
  else {why="The correct answer most directly matches the treatment objective or operating condition described in the question.";tip:"Tie the question back to the purpose of the process before choosing an adjustment."}
  return {why,tip};
}
