function clampHealth(v){return Math.max(0,Math.min(100,Math.round(v)))}
function updateAlarmHud(){["safety","compliance","process","equipment"].forEach(k=>{$("alarm"+k.charAt(0).toUpperCase()+k.slice(1)).textContent=alarmRun.health[k]});let min=Math.min(...Object.values(alarmRun.health));$("alarmBanner").textContent=min<40?"🚨 CRITICAL — DA PLANT STAY HURTING":min<70?"⚠️ PLANT GETTING WORSE":"🚨 BRAH… ALARM!"}
function pickAlarmChain(){let pool=alarmChains.filter(c=>!alarmRun.completed.includes(c.id)&&c.id!=="mega");if(alarmRun.incident===alarmRun.total-1)return alarmChains.find(c=>c.id==="mega");return shuffle(pool)[0]||shuffle(alarmChains.filter(c=>c.id!=="mega"))[0]}
function startAlarmMode(){resetSelfCards("command");alarmRun={chain:null,step:0,incident:0,total:3,health:{safety:100,compliance:100,process:100,equipment:100},escalations:0,score:0,perfect:true,completed:[],lastResult:""};show("alarmGame");startAlarmIncident()}
function startAlarmIncident(){alarmRun.chain=pickAlarmChain();alarmRun.step=0;renderAlarmStep()}
function renderAlarmStep(){renderCommandCards("alarm");let c=alarmRun.chain,stp=c.steps[alarmRun.step];$("alarmDifficulty").textContent=c.level.toUpperCase();$("alarmProgress").textContent="Incident "+(alarmRun.incident+1)+"/"+alarmRun.total+" • Decision "+(alarmRun.step+1)+"/"+c.steps.length;$("alarmStage").textContent=c.icon+" "+c.name;$("alarmTitle").textContent=stp.title;$("alarmSituation").textContent=stp.situation;$("alarmFeedback").textContent="Choose da BEST FIRST action.";$("alarmNext").classList.add("hidden");$("alarmActions").innerHTML="";let hist=alarmRun.lastResult?"<strong>Last result:</strong> "+escapeHtml(alarmRun.lastResult):"<strong>Shift status:</strong> Verify first. Stabilize second. No panic button.";$("alarmLog").innerHTML=hist;stp.actions.forEach((a,idx)=>{let b=document.createElement("button");b.textContent=String.fromCharCode(65+idx)+". "+a.text;b.onclick=()=>chooseAlarmAction(idx);$("alarmActions").appendChild(b)});updateAlarmHud()}
function chooseAlarmAction(idx){let stp=alarmRun.chain.steps[alarmRun.step],a=stp.actions[idx];[...$("alarmActions").children].forEach(b=>b.disabled=true);let imp=a.impact||{};Object.keys(alarmRun.health).forEach(k=>alarmRun.health[k]=clampHealth(alarmRun.health[k]+Number(imp[k]||0)));if(a.good){let cb=selfActive.commandBonus?75:0;if(selfActive.commandBonus)delete selfActive.commandBonus;alarmRun.score+=150+cb;$("alarmFeedback").textContent="✅ Chee! You stabilized da next problem. +"+(150+cb)+(cb?" • 💪 Run Da Gouch":"")}else{alarmRun.escalations++;alarmRun.perfect=false;alarmRun.score=Math.max(0,alarmRun.score-25);$("alarmFeedback").textContent="❌ Ho brah… plant getting worse. Escalation "+alarmRun.escalations+"/3";if(alarmRun.escalations>=3)badge("🚨 HO BRAH… WHO WAS ON SHIFT?!")};alarmRun.lastResult=a.result;$("alarmLog").innerHTML="<strong>Result:</strong> "+escapeHtml(a.result);updateAlarmHud();$("alarmNext").textContent=alarmRun.step===alarmRun.chain.steps.length-1?(alarmRun.incident===alarmRun.total-1?"Finish Da Shift":"Next Alarm"):("Continue Incident");$("alarmNext").classList.remove("hidden");save();profile()}
$("alarmNext").onclick=()=>{if(alarmRun.step<alarmRun.chain.steps.length-1){alarmRun.step++;renderAlarmStep();return}alarmRun.completed.push(alarmRun.chain.id);alarmRun.incident++;if(alarmRun.incident<alarmRun.total){alarmRun.lastResult="Incident stabilized. New alarm coming in…";startAlarmIncident();return}finishAlarmMode()};
function finishAlarmMode(){st.alarmClears+=3;let avg=Math.round(Object.values(alarmRun.health).reduce((a,b)=>a+b,0)/4),saved=avg>=70&&alarmRun.health.safety>=60&&alarmRun.health.compliance>=60;if(saved){st.alarmSaves++;badge("🧯 Saved Da Shift");st.xp+=300;st.seasonXp+=300}if(st.alarmClears>=10)badge("🚨 Alarm Assassin");if(alarmRun.perfect){st.alarmPerfect++;badge("🔨 Wastewater Hammah")}if(Math.min(...Object.values(alarmRun.health))<35)badge("📞 Call Da DRC");save();profile();syncProfile();$("alarmStage").textContent="SHIFT COMPLETE";$("alarmTitle").textContent=saved?"🧯 SAVED DA SHIFT":"💩 Das Shift Got Away From Us";$("alarmSituation").textContent="Alarm Score: "+alarmRun.score+" • Plant Health: "+avg+"% • Escalations: "+alarmRun.escalations;$("alarmActions").innerHTML="";$("alarmLog").innerHTML=saved?"<strong>Chee!</strong> You verified conditions, stabilized the limiting problems, and kept da plant moving.":"<strong>Review time:</strong> Verification, safety/compliance priority, and controlled changes make the difference.";$("alarmFeedback").textContent=saved?(alarmRun.perfect?"🔨 Wastewater Hammah — clean alarm run!":"🧯 Saved Da Shift achievement check complete."):"Run um again. Next shift, no let da alarms run you.";$("alarmNext").classList.add("hidden")}
if($("alarmBtn"))$("alarmBtn").onclick=()=>startAlarmMode();if($("alarmHome"))$("alarmHome").onclick=()=>show("home");

