function buildBattleDeck(){let source=battlePool(battleType);if(battleStyle==="alarm")source=source.filter(q=>q.y==="scenario"||q.d>=3).concat(bank.filter(q=>q.y==="scenario"));if(battleStyle==="drc")source=adaptivePool().filter(q=>q.d>=4);let eligible=source.filter(q=>q.d<=battleGrade+1);if(!eligible.length)eligible=source.length?source:battlePool(battleType);let p=[];while(p.length<bc)p.push(...shuffle(eligible));return p.slice(0,bc).map((q,idx)=>{let order=shuffle(q.a.map((_,i)=>i));let last=idx===bc-1,pen=idx===bc-2;let alarm=false,paniolo=false,boss=last;if(battleStyle==="full")alarm=(idx===Math.max(1,Math.floor(bc/3))||idx===Math.max(2,Math.floor(bc*2/3))),paniolo=pen;if(battleStyle==="alarm")alarm=!last,paniolo=pen;if(battleStyle==="process")paniolo=pen,alarm=idx===Math.floor(bc/2);if(battleStyle==="drc")alarm=idx>0&&!last,paniolo=pen;if(battleStyle==="quick")alarm=bc>=6&&idx===Math.floor(bc/2);let roundType=boss?"MAYJAH BOSS":paniolo?"PROCESS PANIOLO":alarm?"BRAH… ALARM!":"NORMAL ROUND";return {...q,a:order.map(i=>q.a[i]),c:order.indexOf(q.c),alarm,paniolo,boss,roundType,bossTitle:(battleTypeMeta[battleType]||battleTypeMeta.random).boss}})}
