function startTimer(){clearInterval(timerId);roundStarted=Date.now();let limit=20000;timerId=setInterval(()=>{let left=Math.max(0,limit-(Date.now()-roundStarted));$("timerText").textContent=(left/1000).toFixed(1)+" seconds";$("timerBar").style.width=(left/limit*100)+"%";if(left<=0){clearInterval(timerId);if(!ans[role])submit(-1)}},100)}
function renderBattle(){let q=bdeck[br];$("round").textContent="Round "+(br+1)+"/"+bdeck.length;$("battleTopic").textContent="Grade "+battleGrade+" • "+q.t;$("p1").textContent=hostPlant;$("p2").textContent=guestPlant;$("n1").textContent=host;$("n2").textContent=guest;$("s1").textContent=scores.host;$("s2").textContent=scores.guest;renderBattleHealth();renderBattleCards();$("battleRoundTag").textContent=q.roundType||"NORMAL ROUND";$("battleAlarm").classList.toggle("hidden",!q.alarm);$("battleAlarm").textContent=q.alarm?"🚨 BRAH… ALARM! — plant health at risk":"";$("bossBanner").textContent=q.boss?("👑 "+(q.bossTitle||"MAYJAH BOSS")+" — MAYJAH POINTS"):q.paniolo?"🤠 PROCESS PANIOLO — DOUBLE PROCESS PRESSURE":"";$("bossBanner").classList.toggle("hidden",!(q.boss||q.paniolo));$("roundResult").classList.add("hidden");$("battleQ").textContent=q.q;$("battleA").innerHTML="";$("gameStatus").textContent=(q.boss?"Final Mayjah round":q.paniolo?"Process Paniolo round":q.alarm?"Alarm round":"20 seconds")+" — choose the best answer.";q.a.forEach((a,j)=>{let b=document.createElement("button");b.className="answer";b.textContent=String.fromCharCode(65+j)+". "+a;b.onclick=()=>submit(j);$("battleA").appendChild(b)});startTimer()}
